"use client";
import LegacyPage from "../components/LegacyPage";

const TITLE = "Averages — Contacts";
const STYLE_CSS = "\n  /* ---------- Shared design system — copied verbatim from the other\n     top-level pages (/home//courses//assignments) so this\n     reads as the same app. See architecture-decisions.md re: promoting\n     this to an actual shared stylesheet once there's a build step. ---------- */\n  :root {\n    --accent: #d94a2b;\n    --accent-dark: #a8331a;\n    --accent-ring: rgb(from var(--accent) r g b / 0.35);\n    --page-bg-start: #f17b53;\n    --page-bg-end: #930500;\n    --panel-bg: #eaeaec;\n    --panel-inner: #dcdce0;\n    --text-dark: #14151f;\n    --text-muted: #4b4d63;\n    --text-faint: #83849a;\n    --border: #cfcfd6;\n    --window-radius-lg: 22px;\n    --window-radius-md: 14px;\n    --window-radius-sm: 10px;\n    --grade-good: #2f7d54;\n    --grade-mid: #a67a22;\n    --grade-bad: #b6432f;\n  }\n\n  * { box-sizing: border-box; }\n\n  /* Scrollbars app-wide: a slim, permanently-visible, rounded gray bar\n     sitting slightly inset from the true edge of its scrollable area --\n     like a normal OS/Gmail-style scrollbar, not hidden and not\n     hover-gated. (An earlier hover-only version turned out unreliable:\n     the outer page counts as \"hovered\" almost the entire time you're\n     using it, so it either showed constantly or never, depending on the\n     browser -- not the meaningful hover signal it needed to be.)\n     Scrolling itself always works via wheel/trackpad/touch/keys either\n     way. One universal rule (the `*` selector) so it covers every\n     scrollable element automatically — the outer page scroll, every\n     popup/modal, every internal list — without repeating it per\n     element. (The bottom nav's own horizontal scroll strip is a\n     deliberate exception — see .app-nav-inner further down — that one\n     stays permanently hidden as a mobile overflow safety net.) */\n  * {\n    scrollbar-width: thin;\n    scrollbar-color: rgba(20, 21, 31, 0.28) transparent;\n  }\n  *::-webkit-scrollbar { width: 10px; height: 10px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb {\n    background-color: rgba(20, 21, 31, 0.28);\n    border-radius: 999px;\n    border: 2px solid transparent;\n    background-clip: padding-box; /* the transparent border creates the\n      inset gap around the thumb, so it reads as sitting inside the\n      window rather than flush against the very edge */\n  }\n  *::-webkit-scrollbar-thumb:hover { background-color: rgba(20, 21, 31, 0.45); }\n  *::-webkit-scrollbar-corner { background: transparent; }\n\n  /* Declared so the browser themes ITS OWN chrome — scrollbars, the\n\n     overscroll gutter, form controls — against this page rather than\n\n     guessing. Without it Firefox drew a light-theme scrollbar over the\n\n     dark canvas and tinted it (Martin saw it as pink on a blue\n\n     background). LegacyPage's applyStoredTheme() updates both of these\n\n     to match whatever background the user actually saved. */\n\n  html {\n\n    color-scheme: dark;\n\n    background-color: #0c0c0e;\n\n  }\n\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    min-height: 100%;\n    font-family: \"puffin\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  }\n\n  body {\n    height: 100vh; /* fixed, not min -- body itself no longer scrolls */\n    overflow: hidden; /* scrolling now happens inside .page (see below), so\n      the scrollbar sits at the edge of the app's own window/card instead of\n      out at the browser's outer edge, over the wallpaper margin */\n    /* Neutral black instead of a baked-in accent gradient here —\n       2026-09-11, per Martin. This is only ever visible for a split\n       second on reload/navigation, before applyStoredTheme() (or this\n       page's own appearance-reading script) sets the user's actual\n       saved background over it. The old default was the sample\n       red-orange gradient baked into this file, which read as a real\n       glitch flashing in between pages; a neutral black reads as\n       \"still loading\" instead, and matches the app's own Black\n       preset (#0c0c0e) so it's not a color that appears nowhere else\n       in the app. */\n    background-color: #0c0c0e;\n    background-image: none;\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    padding: 40px 24px 100px;\n    display: flex;\n    justify-content: center;\n  }\n\n  .page {\n    width: 100%;\n    max-width: 980px;\n    align-self: stretch; /* fill body's available height regardless of\n      whatever align-items body declares, so there's a bounded box to\n      scroll within */\n    min-height: 0; /* flexbox gotcha: without this, a flex item won't\n      shrink below its content size, which breaks overflow scrolling */\n    overflow-y: auto; /* the actual scroll happens here -- .card grows to\n      its natural content height and .page scrolls as a whole */\n    overflow-x: hidden;\n  }\n\n  /* ---------- Top bar ---------- */\n  .topbar {\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    margin: 0 4px 18px;\n  }\n\n  h1.title {\n    color: #ffffff;\n    font-size: clamp(1.6rem, 3.4vw, 2.1rem);\n    font-weight: 900;\n    font-style: italic;\n    letter-spacing: -0.01em;\n    margin: 0;\n    transform: skewX(-2deg);\n    display: inline-block;\n  }\n  .subtitle {\n    color: rgba(255,255,255,0.85);\n    font-weight: 700;\n    font-style: italic;\n    font-size: 0.9rem;\n    margin: 2px 0 0 2px;\n  }\n\n  .profile-menu-wrap { position: relative; flex-shrink: 0; }\n  .profile-btn {\n    width: 42px;\n    height: 42px;\n    border-radius: 50%;\n    background: rgba(255,255,255,0.2);\n    border: 2px solid rgba(255,255,255,0.5);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.95rem;\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n  .profile-menu {\n    position: absolute;\n    top: calc(100% + 10px);\n    right: 0;\n    min-width: 160px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 25;\n  }\n  .profile-menu-item {\n    display: block;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.86rem;\n    color: var(--text-dark);\n    padding: 9px 12px;\n    cursor: pointer;\n  }\n  .profile-menu-item:hover { background: var(--panel-inner); }\n  .profile-menu-item.signout { color: var(--grade-bad); }\n\n  /* ---------- One card, same as every other page ---------- */\n  .card {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    padding: 6px;\n  }\n  .card-inner {\n    padding: 22px 24px 20px;\n  }\n\n  .section-head {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    margin-bottom: 4px;\n  }\n  .section-head h2 {\n    font-size: 1rem;\n    font-weight: 800;\n    font-style: italic;\n    color: var(--text-dark);\n    margin: 0;\n  }\n  .contacts-total {\n    font-size: 0.76rem;\n    font-weight: 700;\n    color: var(--text-faint);\n  }\n\n  /* ---------- Search bar — same pill input treatment used across the\n     app (/messages's search, the color-swatch popups, etc.). ---------- */\n  .contacts-search-wrap { position: relative; margin: 14px 0 4px; }\n  .contacts-search-wrap svg { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); width: 15px; height: 15px; stroke: var(--text-faint); fill: none; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; pointer-events: none; }\n  #contactsSearch {\n    width: 100%;\n    border: none;\n    border-radius: 999px;\n    background: var(--panel-inner);\n    padding: 9px 14px 9px 34px;\n    font: inherit;\n    font-size: 0.82rem;\n    color: var(--text-dark);\n  }\n  #contactsSearch::placeholder { color: var(--text-faint); }\n  #contactsSearch:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n\n  /* ---------- Contact row — flat, alphabetical, no role/category\n     filters (2026-09-02, per Martin: real faculty records don't\n     consistently have a title/role filled in, so filtering or grouping\n     by it isn't reliable — a plain searchable list, same idea as\n     PowerSchool's own Faculty directory, works for everyone whether or\n     not their role happens to be on file). ---------- */\n  .contact-row { display: flex; align-items: center; gap: 10px; padding: 9px 6px; border-bottom: 1px solid var(--border); cursor: pointer; border-radius: var(--window-radius-sm); }\n  .contact-row:last-child { border-bottom: none; }\n  .contact-row:hover { background: var(--panel-inner); }\n  .contact-row:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring) inset; }\n  .contact-avatar {\n    width: 38px; height: 38px;\n    border-radius: 50%;\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.82rem;\n    display: flex; align-items: center; justify-content: center;\n    flex-shrink: 0;\n  }\n  .contact-text { flex: 1; min-width: 0; }\n  .contact-name { font-weight: 800; font-style: italic; font-size: 0.86rem; color: var(--text-dark); margin: 0; letter-spacing: -0.005em; }\n  .contact-role { font-weight: 500; font-size: 0.78rem; color: var(--text-muted); margin: 1px 0 0; }\n  .contact-meta { font-size: 0.68rem; color: var(--text-faint); margin: 2px 0 0; text-transform: uppercase; letter-spacing: 0.03em; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n  /* Row-level Email quick-action (2026-09-02, per Martin) — a mailto:\n     link, so it works without opening the contact card at all; clicking\n     it stops the row's own click (which opens the card) from firing. */\n  .contact-email-btn {\n    flex-shrink: 0;\n    width: 30px; height: 30px;\n    border-radius: 50%;\n    background: var(--panel-bg);\n    color: var(--accent);\n    border: none;\n    display: flex; align-items: center; justify-content: center;\n    text-decoration: none;\n  }\n  .contact-email-btn:hover { background: var(--accent); color: #fff; }\n  .contact-email-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .contact-email-btn svg { width: 14px; height: 14px; stroke: currentColor; fill: none; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }\n  .contacts-empty { font-size: 0.8rem; color: var(--text-faint); font-style: italic; padding: 10px 0; }\n\n  /* ---------- Contact detail modal — same .modal-overlay/.modal-box\n     component as /course-home's course-info pop-out: dark full-page\n     backdrop, click on the backdrop (not the box) closes it, Escape\n     closes it. Standing popup convention for the whole app. ---------- */\n  .modal-overlay {\n    position: fixed; inset: 0; background: rgba(10, 8, 6, 0.55);\n    display: flex; align-items: center; justify-content: center;\n    padding: 20px; z-index: 60;\n    opacity: 0; visibility: hidden; transition: opacity 0.15s ease;\n  }\n  .modal-overlay.show { opacity: 1; visibility: visible; }\n  .modal-box {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    max-width: 380px; width: 100%;\n    padding: 22px 24px;\n    box-shadow: 0 30px 70px -20px rgba(0,0,0,0.6);\n    transform: translateY(8px);\n    transition: transform 0.15s ease;\n  }\n  .modal-overlay.show .modal-box { transform: translateY(0); }\n  .modal-close {\n    float: right;\n    background: var(--panel-inner);\n    border: none;\n    width: 26px; height: 26px;\n    border-radius: 50%;\n    color: var(--text-muted);\n    cursor: pointer;\n    font-size: 0.9rem;\n    line-height: 1;\n  }\n  .modal-close:hover { color: var(--text-dark); }\n  .contact-modal-head { display: flex; align-items: center; gap: 12px; clear: both; padding-top: 4px; }\n  .contact-modal-avatar {\n    width: 52px; height: 52px;\n    border-radius: 50%;\n    color: #fff;\n    font-weight: 800;\n    font-size: 1.05rem;\n    display: flex; align-items: center; justify-content: center;\n    flex-shrink: 0;\n  }\n  .modal-box h3 { margin: 0; font-size: 1.1rem; font-weight: 900; font-style: italic; color: var(--text-dark); }\n  .modal-code { font-size: 0.78rem; font-weight: 700; color: var(--text-muted); margin: 2px 0 0; }\n  .modal-row { display: flex; justify-content: space-between; gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--border); font-size: 0.8rem; }\n  .modal-row:last-of-type { border-bottom: none; }\n  .modal-row .k { color: var(--text-faint); font-weight: 700; }\n  .modal-row .v { color: var(--text-dark); font-weight: 700; text-align: right; }\n  .modal-rows { margin-top: 14px; }\n  /* Message + Email actions — always both present now (2026-09-02, per\n     Martin: every contact's card should offer a working Send Message\n     button alongside their email, not just current teachers). */\n  .contact-modal-actions { display: flex; gap: 8px; margin-top: 16px; }\n  .contact-modal-btn {\n    display: flex; align-items: center; justify-content: center; gap: 7px;\n    flex: 1;\n    background: var(--accent);\n    color: #fff;\n    border: none;\n    border-radius: 999px;\n    padding: 10px;\n    font: inherit;\n    font-weight: 800;\n    font-size: 0.82rem;\n    cursor: pointer;\n    text-decoration: none;\n  }\n  .contact-modal-btn:hover { background: var(--accent-dark); }\n  .contact-modal-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .contact-modal-btn svg { width: 15px; height: 15px; stroke: currentColor; fill: none; stroke-width: 2.3; stroke-linecap: round; stroke-linejoin: round; }\n  .contact-modal-btn.secondary { background: var(--panel-inner); color: var(--text-dark); }\n  .contact-modal-btn.secondary:hover { background: var(--border); }\n\n  /* ---------- Bottom nav — verbatim from every other page ---------- */\n  .app-nav {\n    position: fixed;\n    left: 0;\n    right: 0;\n    bottom: 20px;\n    display: flex;\n    justify-content: center;\n    padding: 0 20px;\n    z-index: 10;\n    pointer-events: none;\n  }\n  .app-nav-inner {\n    display: flex;\n    gap: 4px;\n    width: 100%;\n    max-width: 940px;\n    overflow-x: auto;\n    scrollbar-width: none;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    padding: 0 8px;\n    pointer-events: auto;\n  }\n  .app-nav-inner::-webkit-scrollbar { display: none; }\n  .nav-link {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 1;\n    min-width: 0;\n    padding: 12px 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-link .label { display: block; max-width: 100%; font-size: 0.72rem; font-weight: 800; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; }\n  .nav-link:hover .label { color: var(--text-muted); }\n  .nav-link .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-link.active .label { color: var(--text-dark); }\n  .nav-link.active .dot { background: var(--accent); }\n  /* ---------- \"More\" overflow (2026-10-01, per Martin: \"if the text has\n     to get ... we should add a more button on the far right side with a\n     list of the other options\"). Labels never truncate: when they would,\n     the rightmost pages move into the More menu instead. ---------- */\n  .nav-link[hidden], .nav-more[hidden], .nav-more-menu[hidden] { display: none; }\n  /* While the More menu is open the whole bar sits above everything else on\n     the page (sticky headers, pop-ups, the edit button go up to z-index 90),\n     so the menu is never drawn underneath them. */\n  .app-nav.more-open { z-index: 1000; }\n  .nav-more {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 0 0 auto;\n    position: relative;\n    margin-left: 4px;\n    padding: 12px 16px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-more .label { display: flex; align-items: center; height: 1.2em; font-size: 0.72rem; color: var(--text-faint); }\n  .nav-more .label svg { display: block; fill: currentColor; }\n  /* thin divider between the pages and the dots */\n  .nav-more::before { content: \"\"; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: var(--border, #cfcfd6); }\n  .nav-more:hover .label, .nav-more[aria-expanded=\"true\"] .label { color: var(--text-dark); }\n  .nav-more .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-more.has-active .label { color: var(--text-dark); }\n  .nav-more.has-active .dot { background: var(--accent); }\n  .nav-more:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-menu {\n    position: absolute;\n    bottom: calc(100% + 8px);\n    right: 20px;\n    min-width: 168px;\n    padding: 8px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);\n    pointer-events: auto;\n  }\n  .nav-more-item {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    font-size: 0.8rem;\n    font-weight: 800;\n    color: var(--text-faint);\n    text-align: left;\n    padding: 12px 12px;\n    border-radius: 8px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n  }\n  .nav-more-item:hover, .nav-more-item:focus-visible { outline: none; color: var(--text-dark); box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-item.active { color: var(--text-dark); }\n  .nav-more-item.active span { position: relative; display: inline-block; padding-bottom: 6px; margin-bottom: -6px; }\n  .nav-more-item.active span::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  /* Labels sit centered in the bar; the active page is underlined in the\n     accent color instead of marked with a dot (2026-10-01, per Martin). */\n  .app-nav-inner .nav-link, .app-nav-inner .nav-more { justify-content: center; gap: 0; padding-top: 10px; padding-bottom: 10px; }\n  .app-nav-inner .nav-link .dot, .app-nav-inner .nav-more .dot { display: none; }\n  .app-nav-inner .nav-link .label, .app-nav-inner .nav-more .label { position: relative; padding: 6px 0; }\n  .app-nav-inner .nav-link.active .label::after, .app-nav-inner .nav-more.has-active .label::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  @media (max-width: 520px) {\n    .nav-more { padding: 10px 12px 8px; }\n    .nav-more::before { top: 10px; bottom: 10px; }\n    .app-nav-inner .nav-link, .app-nav-inner .nav-more { padding-top: 8px; padding-bottom: 8px; }\n    .nav-more .label { font-size: 0.58rem; }\n  }\n  .nav-link:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  @media (max-width: 520px) {\n    .nav-link { min-width: 0; padding: 10px 3px 8px; }\n    .nav-link .label { font-size: 0.58rem; }\n  }\n\n  /* ---------- Signed in: the student's teachers (2026-10-06) ---------- */\n  .modal-row[hidden], .modal-rows[hidden], .contact-modal-btn[hidden], .contact-modal-actions[hidden], .contacts-search-wrap[hidden] { display: none; }\n  .modal-row.is-last { border-bottom: none; }\n  .contacts-state { padding: 24px 8px 12px; text-align: center; font-size: 0.82rem; font-weight: 600; color: var(--text-faint); line-height: 1.45; }\n  .contacts-state p { margin: 0 0 8px; }\n  .contacts-state .contacts-state-title { color: var(--text-dark); font-weight: 800; font-size: 0.9rem; }\n  .contacts-state-btn { border: none; border-radius: 999px; background: var(--accent); color: #fff; font: inherit; font-weight: 800; font-size: 0.8rem; padding: 8px 16px; cursor: pointer; }\n  .contacts-state-btn:hover { background: var(--accent-dark); }\n  .contacts-state-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n";
const BODY_HTML = "\n  <div class=\"page\">\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\">Contacts</h1>\n        <p class=\"subtitle\" id=\"contactsSub\"></p>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\">M</button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-inner\">\n        <div class=\"section-head\">\n          <h2 id=\"contactsHeading\">District Directory</h2>\n          <span class=\"contacts-total\" id=\"contactsTotal\"></span>\n        </div>\n        <div class=\"contacts-search-wrap\" id=\"contactsSearchWrap\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m21 21-4.35-4.35\"/></svg>\n          <input type=\"search\" id=\"contactsSearch\" placeholder=\"Search by name, role, subject, or school\" autocomplete=\"off\" aria-label=\"Search contacts\">\n        </div>\n        <div id=\"contactsListBody\"></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"modal-overlay\" id=\"contactModal\">\n    <div class=\"modal-box\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modalContactName\">\n      <button class=\"modal-close\" id=\"modalCloseBtn\" type=\"button\" aria-label=\"Close contact info\">✕</button>\n      <div class=\"contact-modal-head\">\n        <span class=\"contact-modal-avatar\" id=\"modalAvatar\"></span>\n        <div>\n          <h3 id=\"modalContactName\"></h3>\n          <p class=\"modal-code\" id=\"modalContactRole\"></p>\n        </div>\n      </div>\n      <div class=\"modal-rows\">\n        <div class=\"modal-row\"><span class=\"k\" id=\"modalDeptLabel\">Department</span><span class=\"v\" id=\"modalDept\"></span></div>\n        <div class=\"modal-row\"><span class=\"k\">School</span><span class=\"v\" id=\"modalSchool\"></span></div>\n        <div class=\"modal-row\"><span class=\"k\">Email</span><span class=\"v\" id=\"modalEmail\"></span></div>\n        <div class=\"modal-row\"><span class=\"k\">Phone</span><span class=\"v\" id=\"modalPhone\"></span></div>\n      </div>\n      <div class=\"contact-modal-actions\">\n        <button class=\"contact-modal-btn\" id=\"modalMessageBtn\" type=\"button\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>\n          Message\n        </button>\n        <a class=\"contact-modal-btn secondary\" id=\"modalEmailBtn\" href=\"#\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"m3 7 9 6 9-6\"/></svg>\n          Email\n        </a>\n      </div>\n    </div>\n  </div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\" id=\"dock\">\n      <button class=\"nav-link\" type=\"button\" data-page=\"home\" data-href=\"/home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"grades\" data-href=\"/grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"assignments\" data-href=\"/assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"files\" data-href=\"/files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"calendar\" data-href=\"/calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"messages\" data-href=\"/messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link active\" type=\"button\" data-page=\"contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n\n  \n  \n";
const SCRIPT_JS = "\n    // Potato PC Mode on every page (2026-10-04, per Martin). The saved\n    // setting turns off all CSS animations and transitions, makes animate()\n    // calls and smooth scrolling instant, and drops the slanted page title.\n    // Same code as app/lib/theme-boot.ts, which runs it before first paint in\n    // the app; this copy covers the preview and pages theme-boot skips.\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"schoolagy_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'schoolagy_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    // ------------------------------------------------------------------\n    // Shared appearance (accent + background) — 2026-09-08, per Martin:\n    // \"wallpapers + accent colors don't save across pages.\" Settings'\n    // Appearance section (and onboarding's Theme step) are the only\n    // writers of schoolagy_appearance; every other real app page,\n    // including this one, applies whatever's saved there, read-only, on\n    // its own load — same shared-localStorage-record pattern already\n    // used for schoolagy_dark_mode/schoolagy_profile.\n    // ------------------------------------------------------------------\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('schoolagy_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'schoolagy_appearance') applyAppearance();\n      });\n    })();\n\n    // ------------------------------------------------------------------\n    // Signed in (2026-10-06): CONTACTS comes from the \"people\" extra, which\n    // is the student's own teachers (there's no district directory to read\n    // on Schoology or Google Classroom). When that extra didn't arrive, the\n    // const below falls back to the sample directory, which must never\n    // show as real people, so ctSetContacts empties it and the list offers\n    // Try again. Demo sessions keep the sample directory, like the preview.\n    // Google Classroom teachers can't be messaged, so their cards have no\n    // Message button.\n    // ------------------------------------------------------------------\n    const CT_AV = window.__AVERAGES__;\n    const CT_LIVE = !!(CT_AV && CT_AV.data && CT_AV.mode === 'live');\n    const CT_DATA = CT_LIVE ? CT_AV.data : {};\n    const CT_API = window.location.hostname.endsWith('averages.io') ? 'https://api.averages.io' : 'http://localhost:8787';\n    let ctState = CT_LIVE && !Array.isArray(CT_DATA.CONTACTS) ? 'error' : 'ready'; // 'ready' | 'loading' | 'error'\n    let ctClassroom = CT_LIVE && (CT_DATA.platform === 'classroom' || CT_DATA.PEOPLE_PLATFORM === 'classroom');\n    let ctNeedsPermission = CT_LIVE && CT_DATA.PEOPLE_NEEDS_PERMISSION === true;\n\n    function ctText(value, max) {\n      return (value == null ? '' : String(value)).trim().slice(0, max);\n    }\n    function ctSetContacts(list) {\n      const next = (Array.isArray(list) ? list : []).filter(c => c && c.id != null && String(c.id) !== '').map(c => {\n        const color = ctText(c.color, 16);\n        return {\n          id: String(c.id),\n          name: ctText(c.name, 120) || 'Your teacher',\n          role: ctText(c.role, 80),\n          dept: ctText(c.dept, 200),\n          school: ctText(c.school, 120),\n          email: ctText(c.email, 254),\n          phone: ctText(c.phone, 40),\n          // Lands in a style attribute: only a plain hex color gets through.\n          color: /^#[0-9a-f]{6}$/i.test(color) ? color : '#83849a',\n          category: 'myTeachers',\n        };\n      });\n      CONTACTS.length = 0;\n      next.forEach(c => CONTACTS.push(c));\n    }\n    function ctStateHtml() {\n      if (ctState === 'loading') return '<p class=\"contacts-state\" role=\"status\">Loading your teachers…</p>';\n      if (ctState === 'error') {\n        return `<div class=\"contacts-state\" role=\"alert\">\n            <p class=\"contacts-state-title\">We couldn't load your teachers.</p>\n            <p>Check your connection and try again.</p>\n            <button type=\"button\" class=\"contacts-state-btn\" data-action=\"retry-people\">Try again</button>\n          </div>`;\n      }\n      if (CONTACTS.length) return '';\n      if (ctNeedsPermission) {\n        return `<div class=\"contacts-state\">\n            <p class=\"contacts-state-title\">Your teachers aren't showing yet.</p>\n            <p>To see your teachers here, sign out and sign in with Google again and allow Averages to see your class rosters.</p>\n          </div>`;\n      }\n      return `<div class=\"contacts-state\">\n          <p class=\"contacts-state-title\">No teachers yet</p>\n          <p>When your classes list their teachers, they show up here.</p>\n        </div>`;\n    }\n    function ctRenderHeader() {\n      if (!CT_LIVE) {\n        document.getElementById('contactsTotal').textContent = `${CONTACTS.length} people`;\n        document.getElementById('contactsSub').textContent = 'Staff & teachers · Lincoln Unified School District';\n        return;\n      }\n      document.getElementById('contactsHeading').textContent = 'Your teachers';\n      document.getElementById('contactsTotal').textContent = ctState === 'ready' && CONTACTS.length\n        ? `${CONTACTS.length} ${CONTACTS.length === 1 ? 'teacher' : 'teachers'}` : '';\n      document.getElementById('contactsSub').textContent = ctClassroom ? 'From your Google Classroom classes' : 'From your Schoology classes';\n      contactsSearchInput.placeholder = 'Search by name or class';\n    }\n    // The card leaves out lines with nothing on file instead of showing an\n    // empty value, and only offers what works for this teacher.\n    function ctTidyModal(c) {\n      let last = null;\n      [['modalDept', c.dept], ['modalSchool', c.school], ['modalEmail', c.email], ['modalPhone', c.phone]].forEach(([id, value]) => {\n        const row = document.getElementById(id).parentElement;\n        row.hidden = !value;\n        row.classList.remove('is-last');\n        if (value) last = row;\n      });\n      if (last) last.classList.add('is-last');\n      document.querySelector('#contactModal .modal-rows').hidden = !last;\n      document.getElementById('modalDeptLabel').textContent = c.dept.includes(',') ? 'Classes' : 'Class';\n      modalMessageBtn.hidden = ctClassroom;\n      modalEmailBtn.hidden = !c.email;\n      modalMessageBtn.parentElement.hidden = modalMessageBtn.hidden && modalEmailBtn.hidden;\n    }\n    function ctRetry() {\n      ctState = 'loading';\n      renderContactList();\n      ctRenderHeader();\n      fetch(CT_API + '/data/people', { credentials: 'include' })\n        .then(r => { if (!r.ok) throw new Error('http ' + r.status); return r.json(); })\n        .then(data => {\n          if (!data || !Array.isArray(data.CONTACTS)) throw new Error('no contacts');\n          ctSetContacts(data.CONTACTS);\n          if (data.platform) ctClassroom = data.platform === 'classroom';\n          ctNeedsPermission = data.needsPermission === true;\n          ctResort();\n          ctState = 'ready';\n        })\n        .catch(() => { ctState = 'error'; })\n        .then(() => { renderContactList(); ctRenderHeader(); });\n    }\n\n    // ------------------------------------------------------------------\n    // Sample data — district directory (2026-09-02, per Martin: \"I need\n    // to add a contact list of people in the district\"). The six \"My\n    // Teachers\" entries intentionally reuse the exact same id/name/color\n    // keys as /messages's TEACHERS object; everyone else's id is\n    // local to this page. Either way, every contact's Message button\n    // deep-links straight into a real thread with that person\n    // (/messages?compose=<id>, carrying name/dept/color along for\n    // anyone /messages doesn't already know about — see the wiring\n    // at the bottom of /messages's own script).\n    //\n    // No role/department-based filtering or grouping here (removed\n    // 2026-09-02, per Martin: \"teachers don't have to put roles, some do\n    // some don't\" — a real PowerSchool/Schoology faculty record's title\n    // field is often just blank, so filtering or sectioning by it is\n    // unreliable). `role` is shown when a contact happens to have one on\n    // file and simply omitted otherwise — see contactRowHTML below —\n    // same as the reference Faculty page, where plenty of rows show just\n    // a name and no title underneath it. `category` is kept on the data\n    // only as a lightweight internal label (not shown or filtered on).\n    // ------------------------------------------------------------------\n    const CONTACTS = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.CONTACTS) || [\n      // My Teachers — same ids as /messages's TEACHERS.\n      { id: 'cho', name: 'Mr. Cho', role: 'Teacher', dept: 'English Department', school: 'Lincoln High School', email: 'j.cho@lincolnusd.org', phone: '(555) 201-4471', color: '#6b8f5e', category: 'myTeachers' },\n      { id: 'alvarez', name: 'Mr. Alvarez', role: 'Teacher', dept: 'Science Department', school: 'Lincoln High School', email: 'r.alvarez@lincolnusd.org', phone: '(555) 201-4482', color: '#a67a22', category: 'myTeachers' },\n      { id: 'whitfield', name: 'Ms. Whitfield', role: 'Teacher', dept: 'Math Department', school: 'Lincoln High School', email: 'k.whitfield@lincolnusd.org', phone: '(555) 201-4493', color: '#5b6ea3', category: 'myTeachers' },\n      { id: 'bennett', name: 'Mrs. Bennett', role: 'Teacher', dept: 'Social Studies Department', school: 'Lincoln High School', email: 'l.bennett@lincolnusd.org', phone: '(555) 201-4504', color: '#a15c4f', category: 'myTeachers' },\n      { id: 'ortiz', name: 'Sra. Ortiz', role: 'Teacher', dept: 'World Languages Department', school: 'Lincoln High School', email: 'm.ortiz@lincolnusd.org', phone: '(555) 201-4515', color: '#8a6ba1', category: 'myTeachers' },\n      { id: 'reyes', name: 'Coach Reyes', role: 'Teacher', dept: 'Physical Education Department', school: 'Lincoln High School', email: 'd.reyes@lincolnusd.org', phone: '(555) 201-4526', color: '#4f8c8a', category: 'myTeachers' },\n      // Faculty — other teachers not currently teaching this student.\n      // (Nakamura's title is left blank on purpose — see comment above.)\n      { id: 'patterson', name: 'Ms. Patterson', role: 'Teacher', dept: 'Science Department', school: 'Lincoln High School', email: 'e.patterson@lincolnusd.org', phone: '(555) 201-4537', color: '#7a8f4f', category: 'faculty' },\n      { id: 'delgado', name: 'Mr. Delgado', role: 'Teacher', dept: 'Math Department', school: 'Lincoln High School', email: 'a.delgado@lincolnusd.org', phone: '(555) 201-4548', color: '#5b7ea3', category: 'faculty' },\n      { id: 'nakamura-t', name: 'Mrs. Nakamura', role: '', dept: 'English Department', school: 'Lincoln High School', email: 's.nakamura@lincolnusd.org', phone: '(555) 201-4559', color: '#8f6b7a', category: 'faculty' },\n      // Support & Administration — this school.\n      { id: 'simmons', name: 'Dr. Simmons', role: 'Principal', dept: 'Administration', school: 'Lincoln High School', email: 'c.simmons@lincolnusd.org', phone: '(555) 201-4001', color: '#946b3e', category: 'support' },\n      { id: 'osei', name: 'Mrs. Osei', role: 'Assistant Principal', dept: 'Administration', school: 'Lincoln High School', email: 'f.osei@lincolnusd.org', phone: '(555) 201-4012', color: '#6b8f8f', category: 'support' },\n      { id: 'foster', name: 'Ms. Foster', role: 'School Counselor', dept: 'Counseling', school: 'Lincoln High School', email: 'h.foster@lincolnusd.org', phone: '(555) 201-4023', color: '#6b7a9c', category: 'support' },\n      { id: 'okafor', name: 'Mr. Okafor', role: '', dept: 'Counseling', school: 'Lincoln High School', email: 'n.okafor@lincolnusd.org', phone: '(555) 201-4034', color: '#9c6b8a', category: 'support' },\n      { id: 'lindqvist', name: 'Mrs. Lindqvist', role: 'Librarian', dept: 'Media Center', school: 'Lincoln High School', email: 'a.lindqvist@lincolnusd.org', phone: '(555) 201-4045', color: '#7a7050', category: 'support' },\n      { id: 'ramirez', name: 'Nurse Ramirez', role: 'School Nurse', dept: 'Health Office', school: 'Lincoln High School', email: 'p.ramirez@lincolnusd.org', phone: '(555) 201-4056', color: '#a15c5c', category: 'support' },\n      { id: 'yusuf', name: 'Mr. Yusuf', role: '', dept: 'Athletics', school: 'Lincoln High School', email: 'b.yusuf@lincolnusd.org', phone: '(555) 201-4067', color: '#4f7a5c', category: 'support' },\n      // District Office — spans every school in the district, not just this one.\n      { id: 'whitmore', name: 'Dr. Whitmore', role: 'Superintendent', dept: 'District Office', school: 'Lincoln Unified School District', email: 't.whitmore@lincolnusd.org', phone: '(555) 201-1001', color: '#5c5c8a', category: 'district' },\n      { id: 'alvarado', name: 'Ms. Alvarado', role: 'IT Help Desk', dept: 'District Office', school: 'Lincoln Unified School District', email: 'helpdesk@lincolnusd.org', phone: '(555) 201-1002', color: '#4f7d8f', category: 'district' },\n      { id: 'chen', name: 'Mr. Chen', role: 'Director of Special Education', dept: 'District Office', school: 'Lincoln Unified School District', email: 'w.chen@lincolnusd.org', phone: '(555) 201-1003', color: '#8f6b4f', category: 'district' },\n    ];\n    // Signed in: real teachers only, never the sample directory (2026-10-06).\n    if (CT_LIVE) ctSetContacts(CT_DATA.CONTACTS);\n\n    /**\n     * Escapes a value for interpolation into an HTML string.\n     *\n     * CONTACTS is replaced at build time with live Schoology directory data,\n     * and staff names/departments are attacker-influenced text, so dropping\n     * them straight into an `.innerHTML` template would let a name like\n     * `<img src=x onerror=...>` execute in our origin. Coerces with String()\n     * rather than assuming a string, because nothing shape-checks the live\n     * bundle on the way in.\n     *\n     * NOTE: do not wrap values that are themselves HTML — escaping markup\n     * would print visible tags.\n     */\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, ch => (\n        { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]\n      ));\n    }\n\n    function initials(name) {\n      const parts = name.replace(/^(Mr\\.|Mrs\\.|Ms\\.|Mx\\.|Dr\\.|Sra\\.|Sr\\.|Coach|Nurse)\\s+/i, '').split(' ');\n      return parts.map(p => p[0]).join('').slice(0, 2).toUpperCase();\n    }\n\n    // Sorted by last name (title stripped first), matching the reference\n    // Faculty page's own ordering (Abassy, Alex, Alexander, Alexander,\n    // Alvarado, ...).\n    function lastNameKey(name) {\n      const stripped = name.replace(/^(Mr\\.|Mrs\\.|Ms\\.|Mx\\.|Dr\\.|Sra\\.|Sr\\.|Coach|Nurse)\\s+/i, '').trim();\n      const parts = stripped.split(/\\s+/);\n      return parts[parts.length - 1].toLowerCase();\n    }\n    const CONTACTS_SORTED = [...CONTACTS].sort((a, b) => lastNameKey(a.name).localeCompare(lastNameKey(b.name)));\n    // After Try again brings the teachers in (2026-10-06).\n    function ctResort() {\n      const sorted = [...CONTACTS].sort((a, b) => lastNameKey(a.name).localeCompare(lastNameKey(b.name)));\n      CONTACTS_SORTED.length = 0;\n      sorted.forEach(c => CONTACTS_SORTED.push(c));\n    }\n\n    function contactRowHTML(c) {\n      return `\n        <div class=\"contact-row\" role=\"button\" tabindex=\"0\" data-id=\"${escapeHtml(c.id)}\" aria-label=\"${escapeHtml(c.name)}${c.role ? ', ' + escapeHtml(c.role) : ''}\">\n          <span class=\"contact-avatar\" style=\"background:${escapeHtml(c.color)}\">${escapeHtml(initials(c.name))}</span>\n          <div class=\"contact-text\">\n            <p class=\"contact-name\">${escapeHtml(c.name)}</p>\n            ${c.role ? `<p class=\"contact-role\">${escapeHtml(c.role)}</p>` : ''}\n            ${c.dept || c.school ? `<p class=\"contact-meta\">${[c.dept, c.school].filter(Boolean).map(v => escapeHtml(v)).join(' · ')}</p>` : ''}\n          </div>\n          ${c.email ? `<a class=\"contact-email-btn\" href=\"mailto:${escapeHtml(c.email)}\" aria-label=\"Email ${escapeHtml(c.name)}\" onclick=\"event.stopPropagation()\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"m3 7 9 6 9-6\"/></svg>\n          </a>` : ''}\n        </div>`;\n    }\n\n    function matchesQuery(c, q) {\n      if (!q) return true;\n      const hay = `${c.name} ${c.role} ${c.dept} ${c.school}`.toLowerCase();\n      return hay.includes(q);\n    }\n\n    function renderContactList() {\n      const q = contactsSearchInput.value.trim().toLowerCase();\n      const body = document.getElementById('contactsListBody');\n      // Signed in (2026-10-06): loading, couldn't load, needs the rosters\n      // permission, or no teachers yet.\n      if (CT_LIVE) {\n        const state = ctStateHtml();\n        document.getElementById('contactsSearchWrap').hidden = !!state;\n        if (state) { body.innerHTML = state; return; }\n      }\n      const items = CONTACTS_SORTED.filter(c => matchesQuery(c, q));\n      body.innerHTML = items.length\n        ? items.map(contactRowHTML).join('')\n        : `<p class=\"contacts-empty\">No contacts match \"${escapeHtml(contactsSearchInput.value.trim())}\".</p>`;\n    }\n\n    const contactsSearchInput = document.getElementById('contactsSearch');\n    contactsSearchInput.addEventListener('input', renderContactList);\n\n    renderContactList();\n    ctRenderHeader();\n\n    // ------------------------------------------------------------------\n    // Contact detail modal — same .modal-overlay/.modal-box open/close\n    // convention as /course-home's course-info pop-out (darkens the\n    // rest of the page, backdrop click or Escape closes it).\n    // ------------------------------------------------------------------\n    const contactModal = document.getElementById('contactModal');\n    const modalMessageBtn = document.getElementById('modalMessageBtn');\n    const modalEmailBtn = document.getElementById('modalEmailBtn');\n\n    function openContactModal(c) {\n      document.getElementById('modalAvatar').textContent = initials(c.name);\n      document.getElementById('modalAvatar').style.background = c.color;\n      document.getElementById('modalContactName').textContent = c.name;\n      document.getElementById('modalContactRole').textContent = c.role || c.dept;\n      document.getElementById('modalDept').textContent = c.dept;\n      document.getElementById('modalSchool').textContent = c.school;\n      document.getElementById('modalEmail').textContent = c.email;\n      document.getElementById('modalPhone').textContent = c.phone;\n      // Every contact gets a working Message button now (2026-09-02, per\n      // Martin) — it deep-links into /messages?compose=<id>, passing\n      // name/dept/color along too so /messages can build a thread\n      // header for anyone that isn't already one of its own TEACHERS\n      // (see the wiring at the bottom of /messages's own script).\n      modalMessageBtn.onclick = () => {\n        const url = `/messages?compose=${encodeURIComponent(c.id)}`\n          + `&name=${encodeURIComponent(c.name)}`\n          + `&dept=${encodeURIComponent(c.dept)}`\n          + `&color=${encodeURIComponent(c.color)}`;\n        window.location.href = url;\n      };\n      modalEmailBtn.href = `mailto:${c.email}`;\n      if (CT_LIVE) ctTidyModal(c);\n      contactModal.classList.add('show');\n      document.getElementById('modalCloseBtn').focus();\n    }\n    function closeContactModal() { contactModal.classList.remove('show'); }\n\n    document.getElementById('contactsListBody').addEventListener('click', e => {\n      const row = e.target.closest('.contact-row');\n      if (!row) return;\n      const c = CONTACTS.find(x => x.id === row.dataset.id);\n      if (c) openContactModal(c);\n    });\n    document.getElementById('contactsListBody').addEventListener('keydown', e => {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      const row = e.target.closest('.contact-row');\n      if (!row) return;\n      e.preventDefault();\n      const c = CONTACTS.find(x => x.id === row.dataset.id);\n      if (c) openContactModal(c);\n    });\n    document.getElementById('modalCloseBtn').addEventListener('click', closeContactModal);\n    if (CT_LIVE) {\n      document.getElementById('contactsListBody').addEventListener('click', e => {\n        if (e.target.closest('[data-action=\"retry-people\"]')) ctRetry();\n      });\n    }\n    contactModal.addEventListener('click', e => { if (e.target === contactModal) closeContactModal(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && contactModal.classList.contains('show')) closeContactModal(); });\n\n    // Deep link: /contacts?open=<id> opens straight to that person's\n    // card (2026-09-08, added so /messages's \"View full contact\" link\n    // — from the To box's contact info popup — actually lands on the right\n    // record instead of just the general directory).\n    (function openFromQueryParam() {\n      const id = new URLSearchParams(location.search).get('open');\n      if (!id) return;\n      const c = CONTACTS.find(x => x.id === id);\n      if (c) openContactModal(c);\n    })();\n\n    // Nav — Home/Courses/Grades/Assignments/Messages are real links\n    // between real pages (same full-mesh convention every other page\n    // uses); Calendar/Settings stay visual-only placeholders until those\n    // pages exist.\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) { window.location.href = link.dataset.href; return; }\n        document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));\n        link.classList.add('active');\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — same behavior as every other page.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    // Shared profile photo/name (2026-09-07) — /settings's Edit\n    // Profile modal is the only place this is ever set, but every other\n    // page's top-right profile button used to just show a fixed \"M\" no\n    // matter what was saved there: the button never read anything back,\n    // so a photo you set in Settings was invisible the moment you left\n    // it. schoolagy_profile is the same localStorage record\n    // /settings writes on every save; this is read-only here.\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('schoolagy_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile) return;\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n      } else if (profile.name) {\n        profileBtn.textContent = profile.name.trim().charAt(0).toUpperCase() || 'M';\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n    function openProfileMenu() { profileMenu.hidden = false; profileBtn.setAttribute('aria-expanded', 'true'); }\n    function closeProfileMenu() { profileMenu.hidden = true; profileBtn.setAttribute('aria-expanded', 'false'); }\n    profileBtn.addEventListener('click', () => { if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu(); });\n    document.addEventListener('click', e => { if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); } });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n  \n\n\n    // Back link (2026-10-01, per Martin: \"where it returns to ... is always\n    // wrong\"). Every page records itself in a short per-tab trail; a page's\n    // back link then says and goes to the page before it (\"Back to AP\n    // Chemistry Hub\", \"Back to Grades\"...). With no trail (the page was\n    // opened directly) the page's own default back link is left alone.\n    (function () {\n      const SELF = '/contacts';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Contacts';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

export default function Page() {
  return (
    <LegacyPage
      title={TITLE}
      styleCss={STYLE_CSS}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      requiresAuth={true}
      usesSavedTheme={true}
      hasUploads={false}
      externalScripts={[]}
      pageId={"contacts"}
    />
  );
}
